            animal.setDisease(mate.getDisease());
        }
    }

    /**
     * Returns true if the animal's disease kills it this step.
     */
    public boolean isLethalStep()
    {
        return animal.isDiseased()
                && animal.getDisease().getLethalityRate() <= rand.nextDouble();
    }
